function screen(r){
 switch(r){
 case 'dashboard':return dashboard();
 case 'branches':return branchesScreen();
 case 'students':return studentsScreen();
 case 'classes':return classesScreen();
 case 'approvals':return approvalsScreen();
 case 'academics':return academicsScreen();
 case 'attendance':return attendanceScreen();
 case 'marks':return marksScreen();
 case 'fees':return feesScreen();
 case 'finance':return financeScreen();
 case 'communication':return communicationScreen();
 case 'senders':return sendersScreen();
 case 'settings':return settingsScreen();
 case 'roles':return rolesScreen();
 case 'audit':return auditScreen();
 case 'reports':return reportsScreen();
 case 'profile':return profileScreen();
 case 'notifications':return notificationsScreen();
 case 'timetable':return timetableScreen();
 case 'exams':return examsScreen();
 case 'calendar':return calendarScreen();
 case 'announcements':return announcementsScreen();
 case 'homework':return homeworkScreen();
 case 'documents':return documentsScreen();
 case 'design':return designScreen();
 case 'denied':return deniedScreen();
 case 'more':return moreScreen();
 default:return MODULES[r]?genericList(r):deniedScreen();
 }
}
function approvalRows(){
 return ['admissions','transfers','marks','lessonplans','leave','exams','timetables','payroll'].flatMap(k=>scope(db[k]||[],k).filter(x=>x.status==='Pending approval'&&can('approve',k,x)).map(x=>({...x,kind:k})));
}
function financeChart(){
 const factor=branch==='all'?1:(db.branches.find(b=>b.id===branch)?.collected||1842500)/4147500;
 return `<div class="mini-kpi"><div><b>${money(4147500*factor)}</b><span>Total collected</span></div><div><b>94.2<span style="font-size:12px;margin:0">%</span></b><span>Collection rate</span></div></div><div class="chart-wrap"><svg class="chart" viewBox="0 0 600 225" role="img" aria-label="Illustrative monthly collections rise from May to October 2026"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#a79acb" stop-opacity=".25"/><stop offset="100%" stop-color="#a79acb" stop-opacity="0"/></linearGradient></defs>${[25,70,115,160].map((y,i)=>`<path class="grid" d="M45 ${y}H587"/><text x="0" y="${y+4}">${[50,40,30,20][i]}L</text>`).join('')}<path d="M45 149C85 149 100 126 150 127S205 150 259 108 321 114 368 86 428 105 477 65 540 74 587 34V185H45Z" fill="url(#area)"/><path d="M45 149C85 149 100 126 150 127S205 150 259 108 321 114 368 86 428 105 477 65 540 74 587 34" stroke="#9d8cc8" fill="none" stroke-width="2.5"/><path d="M45 170C100 165 100 157 150 162S210 145 259 150 320 130 368 137 430 117 477 122 540 104 587 111" stroke="#8b92a4" stroke-dasharray="4 5" fill="none" stroke-width="1.5"/>${['May','Jun','Jul','Aug','Sep','Oct'].map((m,i)=>`<text x="${40+i*107}" y="214">${m}</text>`).join('')}<circle cx="587" cy="34" r="5" fill="#f7f8fb" stroke="#9d8cc8" stroke-width="2"/></svg></div><div class="legend"><span><i style="background:#9d8cc8"></i>Fee collections</span><span><i style="background:#8b92a4"></i>Previous period</span><span style="margin-left:auto">INR · illustrative</span></div>`;
}
function attendanceRing(percent=96.4,total=1248){
 return `<div class="ring-area"><div class="ring"><svg viewBox="0 0 130 130" aria-hidden="true"><circle cx="65" cy="65" r="53" stroke="#e6e8ef"/><circle cx="65" cy="65" r="53" stroke="#a29bb8" stroke-dasharray="${percent*3.33} 333" stroke-linecap="round"/><circle cx="65" cy="65" r="53" stroke="#343640" stroke-dasharray="7 333" stroke-dashoffset="-${percent*3.33+4}"/></svg><div class="ring-center"><b>${percent.toFixed(1)}%</b><span>Present today</span></div></div><div class="ring-legend"><div><i style="background:#a29bb8"></i>Present <b>${Math.round(total*percent/100).toLocaleString('en-IN')}</b></div><div><i style="background:#343640"></i>Absent <b>${Math.round(total*(100-percent-1)/100)}</b></div><div><i style="background:#cfd2dc"></i>On leave <b>${Math.round(total*.01)}</b></div></div></div>`;
}
function quickActions(items){return `<div class="quick-grid">${items.map(([label,action,id,ico])=>`<button class="quick-action" data-action="${action}" data-id="${id}">${icon(ico)}${label}</button>`).join('')}</div>`}
function activityList(limit=4){
 return scope(db.audit).slice(0,limit).map(a=>`<div class="activity"><div class="activity-mark">${icon('history')}</div><div><b>${esc(a.name)}</b><p>${esc(a.actor)} · ${esc(a.target)}</p><small>${esc(a.date)}</small></div></div>`).join('')||empty('No recent activity');
}
function approvalPreview(limit=4){
 const rows=approvalRows();
 return rows.length?rows.slice(0,limit).map(x=>`<div class="approval"><div class="approval-icon">${icon(({admissions:'users',marks:'chart',leave:'calendar',exams:'file'}[x.kind]||'file'))}</div><div><b>${esc(x.name)}</b><small>${TITLES[x.kind]} · ${x.class||branchName(x.branch).split(' · ')[1]}</small></div><button class="arrow-link" data-action="detail" data-id="${x.kind}:${x.id}" aria-label="Review ${esc(x.name)}">${icon('chevron')}</button></div>`).join(''):empty('All caught up','No pending decisions in your scope.');
}
function announcementPreview(){return scope(db.announcements,'announcements').filter(a=>a.status==='Published').slice(0,2).map(a=>`<div class="announcement"><div class="text-small muted">${icon('megaphone')} SCHOOL UPDATE</div><h3>${esc(a.name)}</h3><p>${esc(a.notes).slice(0,130)}…</p><small>${date(a.date)} · ${a.audience}</small><button class="row-link" data-action="detail" data-id="announcements:${a.id}">Read notice →</button></div>`).join('')}
function dashboardDetailed(){
 const hour=new Date().getHours();const greeting='Welcome back, '+account().name.replace('Dr. ','').split(' ')[0];
 const action=role==='owner'?button('View reports','go','reports','','download'):role==='principal'?button('Review approvals','go','approvals','primary','check'):role==='teacher'?button('Take attendance','go','attendance','primary','checkSquare'):role==='office'?button('Record payment','recordPayment','','primary','plus'):button('View timetable','go','timetable','','calendar');
 const intro=heading(greeting,({owner:'Your school network, at a glance. Let’s make today a good one.',principal:'A clear view of your campus, your people, and today’s priorities.',teacher:'A little preparation. A meaningful day of learning.',parent:'Stay close to '+studentName(child).split(' ')[0]+'’s learning journey.',student:'Your classes, your progress, and what’s coming next.',office:'Keep every admission, collection, and transaction in order.'}[role]),action,'YOUR SCHOOL. CONNECTED.');
 if(role==='owner'){
  const branches=scope(db.branches);const students=branches.reduce((a,b)=>a+b.students,0),staff=branches.reduce((a,b)=>a+b.staff,0),att=branches.reduce((a,b)=>a+b.attendance,0)/Math.max(1,branches.length);
  return intro+`<div class="stats">${stat('Total students',students.toLocaleString('en-IN'),'4.8%','vs. last term','users')}${stat('Teaching & staff',staff,'6 new','this term','briefcase')}${stat('Average attendance',att.toFixed(1)+'%','1.2%','vs. last month','checkSquare')}${stat('Fees collected',money(branches.reduce((a,b)=>a+b.collected,0)),'8.6%','this month','wallet')}</div><div class="dashboard-grid"><div class="stack">${panel('Financial overview',financeChart()+`<div class="chart-note">${icon('info')} Collections across ${branches.length} ${branches.length===1?'campus':'campuses'} · Demonstration analytics</div>`,link('View report →','finance','small ghost'),'A healthy view of your school’s finances')}${panel('Campus performance',table(['Campus','Students','Attendance','Status',''],branches.map(b=>`<tr><td>${person(b.name.split(' · ')[1],b.city)}</td><td>${b.students.toLocaleString('en-IN')}</td><td>${b.attendance}%<div class="progress" style="margin-top:6px;width:75px"><span style="width:${b.attendance}%"></span></div></td><td>${status(b.status)}</td><td>${button('View','branchDetail',b.id,'small ghost','chevron')}</td></tr>`)),link('All campuses →','branches','small ghost'))}${panel('Recent activity',activityList(),link('View audit trail →','audit','small ghost'))}</div><div class="stack">${panel('Today’s attendance',attendanceRing(att,students),link('Details','attendance','small ghost'),'Across your active campuses')}${panel('Quick actions',quickActions([['Add branch','createBranch','','school'],['Invite user','create','users','users'],['Send notice','compose','','message'],['Reports','go','reports','chart']]))}${panel('Pending approvals <span class="pill-count">'+approvalRows().length+'</span>',approvalPreview(),link('View all →','approvals','small ghost'))}${panel('School updates',announcementPreview(),link('View all →','announcements','small ghost'))}</div></div>`;
 }
 if(role==='principal'){
  const b=db.branches.find(b=>b.id===branch);return intro+`<div class="stats">${stat('Enrolled students',b.students.toLocaleString('en-IN'),'4.2%','this term','users')}${stat('Present today',b.attendance+'%','1.4%','vs. last month','checkSquare')}${stat('Pending decisions',approvalRows().length,'','need your review','check')}${stat('Open parent concerns',scope(db.complaints).filter(x=>x.status==='Open').length,'','awaiting a response','message')}</div><div class="dashboard-grid"><div class="stack">${panel('Your attention makes a difference',approvalPreview(7),link('Review queue →','approvals','small ghost'),'Applications, academic reviews, and staff requests')}${panel('Teaching & learning',quickActions([['Lesson plans','go','lessonplans','book'],['Results','go','marks','chart'],['Timetables','go','timetable','calendar'],['Teacher reviews','go','academics','users']]))}${panel('Campus activity',activityList(),link('Generate weekly report','reports','small ghost'))}</div><div class="stack">${panel('Attendance & wellbeing',attendanceRing(b.attendance,b.students),link('Monitor →','attendance','small ghost'))}${panel('School announcements',announcementPreview(),button('Create','create','announcements','small','plus'))}${panel('Parent relations',scope(db.complaints).map(c=>`<div class="approval"><div class="approval-icon">${icon('message')}</div><div><b>${esc(c.name)}</b><small>${c.parent} · ${date(c.date)}</small></div>${button('Review','detail','complaints:'+c.id,'small ghost')}</div>`).join(''),link('Manage meetings','meetings','small ghost'))}</div></div>`;
 }
 if(role==='teacher'){
  const drafts=scope(db.marks,'marks').filter(x=>x.status!=='Approved').length;return intro+`<div class="stats">${stat('Classes today','4','','Next class · 10:30 AM','book')}${stat('Attendance tasks','2','','Classes 9 A & 9 B','checkSquare')}${stat('Active assignments',scope(db.homework,'homework').filter(x=>x.status==='Published').length,'','for your classes','file')}${stat('Marks awaiting review',drafts,'','approval in progress','chart')}</div><div class="dashboard-grid"><div class="stack">${panel('Today’s teaching plan',todayLessons(),link('Full timetable →','timetable','small ghost'),'Wednesday · 28 Oct 2026')}${panel('Assignments & submissions',homeworkCards(3),link('All assignments →','homework','small ghost'))}${panel('Students to check in with',table(['Student','Class','Attendance',''],scope(db.students,'students').filter(s=>s.attendance<96).map(s=>`<tr><td>${person(s.name,'A little support goes a long way')}</td><td>${s.class}</td><td>${s.attendance}%</td><td>${button('View progress','studentDetail',s.id,'small ghost')}</td></tr>`)),link('Class roster →','classes','small ghost'))}</div><div class="stack">${panel('Quick actions',quickActions([['Attendance','go','attendance','checkSquare'],['Homework','create','homework','plus'],['Enter marks','enterMarks','','chart'],['Request leave','create','leave','calendar']]))}${panel('School updates',announcementPreview())}${panel('My leave requests',scope(db.leave,'leave').map(x=>`<div class="approval"><div><b>${esc(x.type)}</b><small>${date(x.from)}–${date(x.to)}</small></div>${status(x.status)}${button('View','detail','leave:'+x.id,'small ghost','chevron')}</div>`).join(''))}</div></div>`;
 }
 if(isPortal()){
  const s=db.students.find(s=>s.id===child),balance=scope(db.fees,'fees').filter(f=>f.status!=='Paid').reduce((a,f)=>a+f.amount,0);
  return intro+`<div class="stats">${stat('Attendance',s.attendance+'%','','this academic year','checkSquare')}${stat('Homework due',scope(db.homework,'homework').filter(h=>h.status==='Published').length,'','this week','book')}${stat('Next examination','12 Nov','','Science · 9:00 AM','calendar')}${stat('Fee balance',money(balance),'','due 05 Nov 2026','wallet')}</div><div class="dashboard-grid"><div class="stack">${panel('Learning doesn’t stop at the classroom',homeworkCards(3),link('View homework →','homework','small ghost'),'Upcoming assignments for '+esc(s.name))}${panel('Today at school',todayLessons(),link('Weekly view →','timetable','small ghost'))}${panel('Progress, one step at a time',table(['Assessment','Score','Status',''],scope(db.marks,'marks').filter(m=>m.status==='Approved').map(m=>`<tr><td><strong>${m.name}</strong></td><td>${m.scores[child]??'—'} / ${m.max}</td><td>${status('Approved')}</td><td>${button('Report card','reportCard',m.id,'small','download')}</td></tr>`)))}</div><div class="stack">${panel('Student profile',`<div style="display:flex;align-items:center;gap:15px;margin-bottom:16px"><span class="avatar purple" style="width:54px;height:54px;font-size:18px">${initials(s.name)}</span><div><h2>${s.name}</h2><p class="muted text-small">Class ${s.class} · Roll ${s.roll}<br>Greenwood · Main Campus</p></div></div>${link('View profile','profile','full small')}`)}${panel('School updates',announcementPreview())}${panel('Upcoming events',scope(db.calendar).slice(0,3).map(e=>`<div class="approval"><div class="approval-icon">${icon('calendar')}</div><div><b>${e.name}</b><small>${date(e.date)} · ${e.type}</small></div></div>`).join(''),link('Calendar →','calendar','small ghost'))}</div></div>`;
 }
 const feeBalance=scope(db.fees).filter(f=>f.status!=='Paid').reduce((a,f)=>a+f.amount,0),today=scope(db.payments).filter(p=>p.date===TODAY&&p.status==='Confirmed').reduce((a,p)=>a+p.amount,0);
 return intro+`<div class="stats">${stat('Collections today',money(today),'','confirmed payments','wallet')}${stat('Outstanding fees',money(feeBalance),'','across your campus','clock')}${stat('Pending admissions',scope(db.admissions).filter(a=>a.status==='Pending approval').length,'','awaiting principal','users')}${stat('October payroll',money(scope(db.payroll).reduce((a,p)=>a+p.amount,0)),'','2 staff demo records','briefcase')}</div><div class="dashboard-grid"><div class="stack">${panel('Collections & balances',financeChart(),link('Financial overview →','finance','small ghost'))}${panel('Recent transactions',paymentsTable(),link('All payments →','fees','small ghost'))}${panel('Admissions in progress',table(['Student','Class','Status',''],scope(db.admissions).map(a=>`<tr><td>${person(a.name,a.parent)}</td><td>${a.class}</td><td>${status(a.status)}</td><td>${button('Review','detail','admissions:'+a.id,'small ghost','chevron')}</td></tr>`)),button('New admission','create','admissions','small','plus'))}</div><div class="stack">${panel('Quick actions',quickActions([['Admission','create','admissions','users'],['Collect fee','recordPayment','','wallet'],['Expense','create','expenses','plus'],['Receipt','go','documents','file']]))}${panel('Reconciliation needs attention',scope(db.expenses).filter(e=>e.status==='Pending reconciliation').map(e=>`<div class="approval"><div class="approval-icon">${icon('alert')}</div><div><b>${e.name}</b><small>${money(e.amount)} · Bank confirmation needed</small></div>${button('Review','detail','expenses:'+e.id,'small ghost','chevron')}</div>`).join(''))}${panel('Upcoming collections',scope(db.fees).filter(f=>f.status!=='Paid').slice(0,4).map(f=>`<div class="approval"><div><b>${studentName(f.student)}</b><small>${f.category} · ${date(f.due)}</small></div><b class="money" style="margin-left:auto">${money(f.amount)}</b></div>`).join(''),link('Review dues →','fees','small ghost'))}</div></div>`;
}
function todayLessons(){return table(['Time','Subject & class','Room',''],[['09:00–09:45','Science','9 A','Lab 02','Completed'],['10:30–11:15','Science','9 B','Room 108','Up next'],['12:00–12:45','Science','9 A','Room 104','Scheduled'],['14:00–14:45','Activity / reading','9 B','Library','Scheduled']].filter(x=>!isPortal()||x[2]===studentClass()).map(x=>`<tr><td class="nowrap">${x[0]}</td><td><strong>${x[1]}</strong><small>Class ${x[2]}</small></td><td>${x[3]}</td><td>${status(x[4])}</td></tr>`))}
function branchesScreen(){const rows=filtered(scope(db.branches));return heading('A network. One shared vision.','Manage your schools and campuses from one calm workspace.',button('Add branch','createBranch','','primary','plus'),'SCHOOLS & BRANCHES')+toolbar(scope(db.branches))+`<div class="cards">${rows.map(b=>`<article class="panel branch-card"><div style="display:flex;justify-content:space-between"><span class="school-badge monogram" style="margin:0;padding:10px">${icon('school')}</span>${status(b.status)}</div><h3>${esc(b.name.split(' · ')[1])}</h3><p>${esc(b.school)}</p><p>${esc(b.city)} · ${esc(b.principal)}</p><div class="branch-metrics"><div><b>${b.students.toLocaleString('en-IN')}</b><small>Students</small></div><div><b>${b.staff}</b><small>Staff</small></div><div><b>${b.attendance}%</b><small>Attendance</small></div></div>${button('Open campus','branchDetail',b.id,'full mt','','')}</article>`).join('')||empty()}</div>`}
function studentsScreen(){const rows=filtered(scope(db.students,'students')).filter(s=>!classFilter||role!=='teacher'||s.class===classFilter);return heading('Every student, seen.','Student records are restricted to your assigned scope.',can('export','students')?button('Export roster','export','students','','download'):'')+panel('Student directory',toolbar(scope(db.students,'students'))+(rows.length?table(['Student','Class / roll','Parent / guardian','Attendance','Status',''],rows.map(s=>`<tr><td>${person(s.name,s.id.toUpperCase())}</td><td>${s.class}<small>Roll ${s.roll}</small></td><td>${s.parent}</td><td>${s.attendance}%</td><td>${status(s.status)}</td><td>${button('View','studentDetail',s.id,'small ghost','chevron')}</td></tr>`)):empty()))}
function classesScreen(){return heading('Your classes','A familiar face behind every record.',button('Take attendance','go','attendance','primary','checkSquare'))+`<div class="cards mb">${(account().classes||[...new Set(scope(db.students,'students').map(s=>s.class))]).map(c=>`<article class="panel branch-card"><span class="badge">Science</span><h3>Class ${c}</h3><p>${scope(db.students,'students').filter(s=>s.class===c).length} students in demo roster · Priya Nair</p><div class="branch-metrics"><div><b>96.4%</b><small>Attendance</small></div><div><b>${scope(db.homework,'homework').filter(h=>h.class===c).length}</b><small>Assignments</small></div></div>${button('Open class roster','classRoster',c,'full mt')}</article>`).join('')}</div>`+studentsScreen().replace(/<div class="page-heading">[\s\S]*?<\/div><\/div>/,'')}
function approvalsScreen(){const rows=filtered(approvalRows());return heading('Good decisions start here.','Review the details, leave a clear decision, and keep work moving.',link('Academic review','academics'),'APPROVAL CENTRE')+panel('Awaiting your review <span class="pill-count">'+rows.length+'</span>',toolbar(approvalRows())+(rows.length?table(['Request','Module','Submitted / details','Status',''],rows.slice((page-1)*7,page*7).map(x=>`<tr><td>${person(x.name,x.class||branchName(x.branch))}</td><td>${TITLES[x.kind]}</td><td>${date(x.submitted||x.from||x.date)}<small>${esc(x.notes||x.feedback||'').slice(0,55)}</small></td><td>${status(x.status)}</td><td>${button('Review','detail',x.kind+':'+x.id,'small','chevron')}</td></tr>`)):empty('All caught up','Every request in your scope has a recorded decision.'))+paginate(rows.length))}
function academicsScreen(){return heading('Teaching, with intention.','Review lesson plans, teacher activity, exam schedules, and results.')+`<div class="cards mb">${[['Lesson plans','lessonplans','book'],['Timetables','timetable','calendar'],['Exams & results','marks','chart']].map(([t,r,i])=>`<article class="panel"><div class="panel-head"><h2>${t}</h2>${icon(i)}</div><div class="stat-value">${scope(db[r==='timetable'?'timetables':r]||[]).filter(x=>x.status==='Pending approval').length}</div><p class="muted text-small">Awaiting your review</p>${link('Open review queue',r,'full small')}</article>`).join('')}</div>`+panel('Teacher performance review',table(['Teacher','Assigned classes','Lesson plans','Review',''],scope(db.users,'users').filter(u=>u.role==='teacher').map(u=>`<tr><td>${person(u.name,u.email)}</td><td>${u.class}</td><td>1 submitted</td><td>${status(u.reviews?.at(-1)?.review||'Pending review')}</td><td>${button('Review teacher','teacherReview',u.id,'small')}</td></tr>`)),'','Reviews record comments and follow-up tasks in the audit trail.')}
let attendanceDate=TODAY;
function attendanceKey(){return (branch==='all'?'b1':branch)+'|'+classFilter+'|'+attendanceDate}
function attendanceScreen(){
 const editable=can('mark','attendance'), key=attendanceKey(),existing=db.attendance.find(a=>a.id===key);
 const roster=scope(db.students,'students').filter(s=>isPortal()?s.id===child:s.class===classFilter);
 if(!attendanceDraft[key])attendanceDraft[key]=structuredClone(db.attendanceDraft[key]||existing?.entries||{});
 const entries=attendanceDraft[key],present=Object.values(entries).filter(v=>v==='Present').length,absent=Object.values(entries).filter(v=>v==='Absent').length;
 const select=`<select id="attendance-class" aria-label="Select class">${(role==='teacher'?account().classes:['9 A','9 B','6 B','8 A','7 A']).map(c=>`<option ${classFilter===c?'selected':''}>${c}</option>`).join('')}</select>`;
 if(isPortal())return heading('Showing up. Growing every day.','Attendance and leave for '+esc(studentName(child)),button('Request leave','create','leave','primary','plus'))+`<div class="stats">${stat('Overall attendance',db.students.find(s=>s.id===child).attendance+'%','','academic year 2026–27','checkSquare')}${stat('Approved leave',scope(db.leave,'leave').filter(l=>l.status==='Approved').length,'','recorded leave requests','calendar')}${stat('Attendance records',scope(db.attendance,'attendance').length,'','submitted demo sessions','file')}${stat('School day','Wednesday','','28 Oct 2026','sun')}</div>`+panel('Attendance history',table(['Date','Class','Status','Recorded by'],scope(db.attendance,'attendance').filter(a=>a.entries?.[child]).map(a=>`<tr><td>${date(a.date)}</td><td>${a.class}</td><td>${status(a.entries[child])}</td><td>${a.teacher}</td></tr>`))+(!scope(db.attendance,'attendance').some(a=>a.entries?.[child])?empty('No daily submissions yet','Your overall demo attendance is shown above. A teacher submission will appear here.'):'') )+genericList('leave',{desc:'Track requests and read approval comments.'});
 return heading('A good day starts with attendance.','Choose a class and date to review the daily register.',editable?button(existing?'Submit correction':'Submit attendance','submitAttendance','','primary','checkSquare'):button('Export register','attendanceExport','','','download'),'DAILY REGISTER')+
 `<div class="stats">${stat('Class strength',roster.length,'','demo roster','users')}${stat('Present',present,'','in current register','check')}${stat('Absent',absent,'','follow-up required','clock')}${stat('Register status',existing?'Submitted':db.attendanceDraft[key]?'Draft':'Unmarked','',attendanceDate===TODAY?'Today':'Selected date','file')}</div>`+
 panel('Class register',`<div class="toolbar">${select}<input type="date" class="field" style="width:auto" id="attendance-date" value="${attendanceDate}" max="${TODAY}" aria-label="Attendance date">${editable?button('Mark all present','bulkPresent','','small','check')+button('Save draft','saveAttendance','','small','file'):''}${existing?status('Submitted'):status('Draft')}</div>${existing&&editable?alertBox('Corrections are recorded','A reason is required when you resubmit. Previous values remain in the audit trail.'):''}${!editable?alertBox('View-only register','Only assigned teachers or the owner administrative context can record or correct attendance.'):''}${roster.length?table(['Student','Roll','Attendance',''],roster.map(s=>`<tr><td>${person(s.name,'Class '+s.class)}</td><td>${s.roll}</td><td>${editable?`<div class="attendance-actions">${['Present','Absent','Late','Excused'].map(v=>`<button class="${entries[s.id]===v?'selected '+v.toLowerCase():''}" data-action="markAttendance" data-id="${s.id}:${v}" aria-pressed="${entries[s.id]===v}">${v}</button>`).join('')}</div>`:status(existing?.entries?.[s.id]||'Not submitted')}</td><td>${button('Profile','studentDetail',s.id,'small ghost','chevron')}</td></tr>`),'attendance-table'):empty('No students in this class','Select a class within this campus.')}${editable?`<div class="form-actions">${button('Save draft','saveAttendance','','','file')}${button(existing?'Submit correction':'Submit attendance','submitAttendance','','primary','check')}</div>`:''}`)+panel('Submitted registers',table(['Date','Class','Recorded by','Status',''],scope(db.attendance,'attendance').map(a=>`<tr><td>${date(a.date)}</td><td>${a.class}</td><td>${a.teacher}</td><td>${status(a.status)}</td><td>${button('Open','openRegister',a.id,'small ghost')}</td></tr>`)));
}
function homeworkCards(limit=20){
 const rows=filtered(scope(db.homework,'homework')).slice(0,limit);
 return rows.map(h=>`<div class="approval" style="align-items:flex-start;padding:16px 0"><div class="approval-icon">${icon('book')}</div><div style="flex:1"><b>${esc(h.name)}</b><small>${h.subject} · Class ${h.class} · Due ${date(h.deadline)}</small><div style="margin-top:7px">${status(h.status)} ${isPortal()&&h.submissions?.some(s=>s.student===child)?status('Submitted'):''}</div></div>${button(isPortal()?'Open':'Review','detail','homework:'+h.id,'small ghost','chevron')}</div>`).join('')||empty('No assignments yet','Published work for your class will appear here.');
}
function homeworkScreen(){const rows=scope(db.homework,'homework');return heading(isPortal()?'A little practice, every day.':'Meaningful work, beyond the classroom.',isPortal()?'Instructions, resources, and feedback in one place.':'Create classwork, set deadlines, and support every submission.',can('create','homework')?button('Create assignment','create','homework','primary','plus'):'','HOMEWORK & CLASSWORK')+panel('Assignments',toolbar(rows)+homeworkCards())}
function marksScreen(){
 const rows=filtered(scope(db.marks,'marks'));
 return heading('Progress you can see.','Draft marks are reviewed before students can access their results.',can('mark','marks')?button('Enter marks','enterMarks','','primary','plus'):'','MARKS & PROGRESS')+
 panel('Assessment records',toolbar(scope(db.marks,'marks'))+(rows.length?table(['Assessment','Class / subject','Maximum','Status',''],rows.map(m=>`<tr><td>${person(m.name,'Science department')}</td><td>${m.class}<small>${m.subject}</small></td><td>${m.max}</td><td>${status(m.status)}</td><td>${isPortal()?button('Report card','reportCard',m.id,'small','download'):button('Review marks','detail','marks:'+m.id,'small','chevron')}</td></tr>`)):empty()))+
 panel('Student progress',table(['Student','Attendance','Approved average',''],scope(db.students,'students').map(s=>{let approved=scope(db.marks,'marks').filter(m=>m.status==='Approved'&&m.scores[s.id]!=null);let avg=approved.length?Math.round(approved.reduce((a,m)=>a+m.scores[s.id]/m.max*100,0)/approved.length)+'%':'Awaiting results';return `<tr><td>${person(s.name,s.class)}</td><td>${s.attendance}%</td><td>${avg}</td><td>${button('View profile','studentDetail',s.id,'small ghost')}</td></tr>`})));
}
function paymentsTable(){const rows=filtered(scope(db.payments,'payments'));return rows.length?table(['Payment / student','Date','Amount','Status',''],rows.map(p=>`<tr><td><strong>${esc(p.id)}</strong><small>${studentName(p.student)} · ${p.method}</small></td><td>${date(p.date)}</td><td class="money">${money(p.amount)}</td><td>${status(p.status)}</td><td>${p.status==='Confirmed'?button('Receipt','receipt',p.id,'small','download'):button('View status','paymentStatus',p.id,'small ghost','chevron')}</td></tr>`)):empty('No payments in this scope','Confirmed payments and their receipts appear here.')}
function feesScreen(){
 const rows=scope(db.fees,'fees'),out=rows.filter(f=>f.status!=='Paid'),paid=scope(db.payments,'payments').filter(p=>p.status==='Confirmed').reduce((a,p)=>a+p.amount,0);
 const tab=activeTab||'dues';
 return heading(isPortal()?'School fees, clearly.':'Every collection, accounted for.',isPortal()?'View your fee statement, payment status, and confirmed receipts.':'Collect fees, track outstanding balances, and reconcile records.',can('pay','fees')?button(role==='parent'?'Pay outstanding fees':'Record payment',role==='parent'?'payFees':'recordPayment','','primary','wallet'):button('Download statement','feeStatement','','','download'),'FEES & PAYMENTS')+
 `<div class="stats">${stat('Outstanding balance',money(out.reduce((a,f)=>a+f.amount,0)),'','across selected records','wallet')}${stat('Confirmed payments',money(paid),'','available receipts only','check')}${stat('Overdue fees',money(out.filter(f=>f.status==='Overdue').reduce((a,f)=>a+f.amount,0)),'','follow-up needed','clock')}${stat('Next due date','05 Nov','','2026 · monthly schedule','calendar')}</div>`+
 alertBox('Payment service is not connected','This prototype uses a labelled demo gateway. No money is collected; a click on Pay never confirms a payment.')+
 tabs([['dues','Outstanding fees'],['payments','Payment history'],['allFees','Full statement']],tab)+
 panel(tab==='payments'?'Payment history':tab==='allFees'?'Fee statement':'Outstanding dues',tab==='payments'?toolbar(scope(db.payments,'payments'))+paymentsTable():toolbar(rows)+table(['Fee item','Student','Due date','Amount','Status',''],filtered(tab==='allFees'?rows:out).map(f=>`<tr><td><strong>${esc(f.name)}</strong><small>${f.category}</small></td><td>${studentName(f.student)}</td><td>${date(f.due)}</td><td class="money">${money(f.amount)}</td><td>${status(f.status)}</td><td>${can('pay','fees')&&f.status!=='Paid'?button('Review & pay',role==='parent'?'payFees':'recordPayment',f.id,'small ghost','chevron'):''}</td></tr>`)))+
 (!isPortal()?`<div class="two-col mt">${panel('Fee administration',quickActions([['Structures','go','feeStructures','layers'],['Concessions','go','discounts','percent'],['Fee reminder','compose','Fees','message'],['Reports','go','reports','chart']]))}${panel('Reconciliation',`<p class="muted text-small">Record bank confirmations before marking a payment confirmed. Every adjustment requires a reason.</p>${button('Review pending payments','tab','payments','small')}`)}</div>`:'');
}
function financeScreen(){
 const ex=scope(db.expenses),transactions=scope(db.payments).filter(p=>p.status==='Confirmed'),collected=transactions.reduce((a,p)=>a+p.amount,0),expenses=ex.reduce((a,p)=>a+p.amount,0);
 return heading('Financial clarity. Every day.','Authorized records, clear balances, and a traceable history.',can('create','expenses')?button('Add expense','create','expenses','primary','plus'):'','FINANCE')+
 `<div class="stats">${stat('Confirmed collections',money(collected),'','demo transaction ledger','wallet')}${stat('Recorded expenses',money(expenses),'','selected campus scope','briefcase')}${stat('Net cash position',money(collected-expenses),'','collections less expenses','chart')}${stat('Reconciliation alerts',ex.filter(e=>e.status==='Pending reconciliation').length,'','require bank confirmation','alert')}</div><div class="split"><div class="stack">${panel('Fee collection trend',financeChart(),link('Consolidated report','reports','small ghost'))}${panel('Expense ledger',table(['Expense / vendor','Date','Amount','Status',''],ex.map(e=>`<tr><td><strong>${e.name}</strong><small>${e.vendor}</small></td><td>${date(e.date)}</td><td>${money(e.amount)}</td><td>${status(e.status)}</td><td>${button('Review','detail','expenses:'+e.id,'small ghost','chevron')}</td></tr>`)),link('All expenses','expenses','small ghost'))}</div><div class="stack">${panel('Financial operations',`<div class="check-list">${[['Fee collection','fees','wallet'],['Fee structures & schedules','feeStructures','layers'],['Discounts, scholarships & fines','discounts','percent'],['Vendors & invoices','vendors','briefcase'],['Staff payroll','payroll','users'],['Financial reports','reports','chart']].map(([t,r,i])=>link(t,r,'full',i)).join('')}</div>`)}${panel('Recent transactions',paymentsTable())}</div></div>`;
}
function communicationScreen(){
 const tab=activeTab||'history';
 return heading('The right message. The right people.','A shared communication centre, with your school’s permissions.',can('message','communication')?button('Compose message','compose','','primary','plus'):'','COMMUNICATION')+
 alertBox('WhatsApp is disconnected','Messages are demo records. Scheduling stores a local request; delivery and read receipts require a connected service.')+
 tabs([['history','Message history'],['scheduled','Scheduled'],['inbox','Parent & teacher inbox'],...(role==='owner'?[['senders','Sender management'],['templates','Templates']]:[])],tab)+
 (tab==='senders'?sendersScreen(true):tab==='templates'?genericList('templates'):tab==='inbox'?inboxScreen():messageHistory(tab));
}
function messageHistory(tab){
 let rows=scope(db.messages,'messages');if(tab==='scheduled')rows=rows.filter(m=>m.status.startsWith('Scheduled'));
 if(role==='teacher')rows=rows.filter(m=>m.category!=='Fees');if(role==='office')rows=rows.filter(m=>m.category==='Fees');
 if(isPortal())rows=rows.filter(m=>m.recipients?.includes(child));
 const visible=filtered(rows);
 return panel(tab==='scheduled'?'Scheduled requests':'Message activity',toolbar(rows,`<input id="message-date" type="date" aria-label="Filter message date" style="width:auto" value="${window.messageDate||''}"><select id="message-sender" aria-label="Filter sender"><option value="">All senders</option>${scope(db.senders).map(s=>`<option value="${s.id}" ${window.messageSender===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><select id="message-audience" aria-label="Filter audience"><option value="">All audiences</option>${[...new Set(rows.map(m=>m.audience))].map(s=>`<option ${window.messageAudience===s?'selected':''}>${esc(s)}</option>`).join('')}</select>`)+
 table(['Message','Audience','Schedule / sender','Status',''],visible.filter(m=>(!window.messageDate||m.date===window.messageDate)&&(!window.messageSender||m.sender===window.messageSender)&&(!window.messageAudience||m.audience===window.messageAudience)).map(m=>`<tr><td><strong>${esc(m.name)}</strong><small>${m.category}</small></td><td>${esc(m.audience)}<small>${m.recipients?.length||0} recipients</small></td><td>${date(m.date)} ${m.time||''}<small>${db.senders.find(s=>s.id===m.sender)?.number||'In-app'}</small></td><td>${status(m.status)}</td><td>${button('Details','messageDetail',m.id,'small ghost','chevron')}</td></tr>`))+(visible.length?'':empty('No messages yet','Compose a message or clear your filters.')));
}
function inboxScreen(){
 if(!db.settings.messaging)return panel('Teacher messaging is disabled',empty('Messaging is unavailable','Your school has disabled direct teacher messaging.'));
 const rows=scope(db.conversations,'conversations').filter(c=>!isPortal()||c.student===child);
 return panel('School conversations',rows.map(c=>`<div class="approval"><div class="avatar">${initials(isPortal()?c.teacher:studentName(c.student))}</div><div style="flex:1"><b>${isPortal()?c.teacher:studentName(c.student)+'’s family'}</b><small>${esc(c.messages.at(-1)?.text||'Start a conversation').slice(0,85)}</small></div>${button('Open','conversation',c.id,'small','message')}</div>`).join('')||empty('No conversations yet','An authorized teacher can open a conversation from a student profile.'));
}
function sendersScreen(embedded=false){const rows=scope(db.senders);return (embedded?'':heading('A trusted school identity.','Configure sender numbers and category routing. Credentials stay masked.',button('Add sender','addSender','','primary','plus'),'WHATSAPP ADMINISTRATION'))+
 (embedded?`<div class="mb">${button('Add sender','addSender','','primary','plus')}</div>`:'')+
 `<div class="cards">${rows.map(s=>`<article class="panel branch-card"><div class="panel-head">${icon('message')}${status(s.status)}</div><h3>${esc(s.name)}</h3><p>${esc(s.number)} ${s.default?'<span class="badge">Default</span>':''}</p><p>${branchName(s.branch)}</p><div class="divider mt"></div><p>Credential · ${s.credential||'Not configured'}</p><p>Categories · ${s.categories.join(', ')}</p><div class="form-actions">${button('Configure','editSender',s.id,'small','settings')}${!s.default?button('Set default','defaultSender',s.id,'small'):''}</div></article>`).join('')}</div>`+alertBox('Live setup is required','Connect an approved WhatsApp provider and verify each number in a production integration. This frontend does not store provider secrets.');
}
